buggy.oob_intstring_scalar_array:
import numpy as np

records = []

def try_scalar(dtype_str, s):
    dtype = getattr(np, dtype_str)
    try:
        v = dtype(s)
        return ("value", str(dtype_str), s, v)
    except Exception as e:
        return ("exc", str(dtype_str), s, type(e).__name__)


def try_array(dtype_str, s):
    dtype = getattr(np, dtype_str)
    try:
        a = np.array([s], dtype=dtype)
        return ("value", str(dtype_str), s, a.tolist())
    except Exception as e:
        return ("exc", str(dtype_str), s, type(e).__name__)


# Choose examples expected to wrap at least for some dtype on buggy.
examples = [
    ("int32", "2147483648"),   # iinfo.max + 1
    ("int8", "128"),           # iinfo.max + 1
    ("uint8", "-1"),          # iinfo.min - 1 for unsigned
]

for dt, s in examples:
    records.append(try_scalar(dt, s))
    # also exercise array/reshape paths
    records.append(try_array(dt, s))

# 0-d array creation (np.array(s, dtype=...))
for dt, s in examples:
    dtype = getattr(np, dt)
    try:
        a0 = np.array(s, dtype=dtype)
        records.append(("value", str(dt)+"[0d]", s, a0.item()))
    except Exception as e:
        records.append(("exc", str(dt)+"[0d]", s, type(e).__name__))

# Emit as a flat list so the harness stores structured values.
probe("wrap_results", records)

buggy.oob_intstring_overflow_vs_wrap:
import numpy as np

def conv(dtype, s):
    try:
        v = np.array(s, dtype=dtype).item()  # exercises scalar/array paths
        return ("value", v)
    except Exception as e:
        return ("exc", type(e).__name__)

cases = [
    (np.int32, '2147483648'),
    (np.int8, '128'),
    (np.uint8, '-1'),
    (np.int32, str(np.iinfo(np.int32).max + 1)),
]

out = {}
for dt, s in cases:
    tag, val = conv(dt, s)
    out[f"{dt.__name__}:{s}"] = (tag, val)

# also test min-1 and max+1 for a representative dtype
for s in [str(np.iinfo(np.int32).min - 1), str(np.iinfo(np.int32).max + 1)]:
    tag, val = conv(np.int32, s)
    out[f"int32:{s}"] = (tag, val)

probe(out)

